/// <summary>
///    Periodic batch job to sync Entra ID Group membership information
///    and maintain security role assignments.
/// </summary>
/// <remarks>
///    This class adds one or more batch tasks.
/// </remarks>
public class ADMEntraIdGroupUserSynchronization extends RunBaseBatch implements BatchRetryable
{
    UserId userId;

    DialogField dialogUserId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        userId
    #endmacro
}

Method.Source:
/// <summary>
/// Indicates whether the job can run in batch mode.
/// </summary>
/// <returns>
/// Always returns true.
/// </returns>
public boolean canGoBatch()
{
    return true;
}

/// <summary>
///    Determines whether the class is shown in the list of <c>Journal</c> types.
/// </summary>
/// <returns>
///    true if the class is shown in the list of <c>Journal</c> types; otherwise, false.
/// </returns>
public boolean canGoBatchJournal()
{
    return true;
}

/// <summary>
/// Calls standard SysSecurityDynamicRoleAssignment::synchronize(roleId) once per
/// distinct security role currently assigned (via SecurityUserRole with
/// AssignmentStatus == Enabled) to any group in the supplied dirtyGroups set.
/// </summary>
/// <param name = "_dirtyGroups">
/// Set of Entra ID group user ids (UserInfo.id) whose membership was refreshed
/// successfully during this run AND actually changed.
/// </param>
/// <remarks>
/// Deduplicating per role (rather than per user/group) keeps the work proportional
/// to the number of affected roles. The standard synchronize method evaluates
/// SecurityRoleAssignmentRule records for the role against the current content of
/// ADMEntraIdGroupUserMembership and materialises / removes SecurityUserRole rows
/// accordingly. Direct (non-rule) SecurityUserRole rows are not touched.
/// </remarks>
protected void synchronizeRolesForDirtyGroups(Set _dirtyGroups)
{
    if (!_dirtyGroups || _dirtyGroups.elements() == 0)
    {
        return;
    }

    SecurityUserRole    secUserRole;
    Set                 processedRoles = new Set(Types::Int64);
    SetEnumerator       groupEnum = _dirtyGroups.getEnumerator();
    int                 rolesSynchronized = 0;
    UserId              groupId;

    while (groupEnum.moveNext())
    {
        groupId = groupEnum.current();

        while select SecurityRole from secUserRole
            where secUserRole.User == groupId
               && secUserRole.AssignmentStatus == RoleAssignmentStatus::Enabled
        {
            if (secUserRole.SecurityRole == 0 || processedRoles.in(secUserRole.SecurityRole))
            {
                continue;
            }

            processedRoles.add(secUserRole.SecurityRole);

            unchecked(Uncheck::TableSecurityPermission)
            {
                SysSecurityDynamicRoleAssignment::synchronize(secUserRole.SecurityRole);
            }

            rolesSynchronized++;
        }
    }

    if (rolesSynchronized > 0)
    {
        info(strFmt("@D365FOAdminToolkit:EntraIdGroupRoleSyncCompleted", rolesSynchronized, _dirtyGroups.elements()));
    }
}

/// <summary>
/// Indicates whether the batch task is run on the server or on a client.
/// </summary>
/// <returns>
/// Always returns true.
/// </returns>
/// <remarks>
/// Your classes that extend this class must override the <c>runsImpersonated</c> method and return
/// false if you want those tasks to run on a client.
/// </remarks>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public boolean runsImpersonated()
{
    return true;
}

/// <summary>
///    Constructs a new class instance.
/// </summary>
/// <returns>An instance of the <c>ADMUserEntraIdGroupSynchronization</c> class.</returns>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public static ADMEntraIdGroupUserSynchronization construct()
{
    return new ADMEntraIdGroupUserSynchronization();
}

/// <summary>
///    Internal use only.
/// </summary>
/// <param name="_args">An instance of the <c>Args</c> class.</param>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public static void main(
    Args _args)
{
    ADMEntraIdGroupUserSynchronization entraIdGroupSync = ADMEntraIdGroupUserSynchronization::construct();

    if (entraIdGroupSync.prompt())
    {
        entraIdGroupSync.runOperation();
    }
}

/// <summary>
/// Get or set the userId variable
/// </summary>
/// <param name = "_userId">
/// A user for which to perform the synchronization; optional.
/// </param>
/// <returns>A userId value</returns>
public UserId parmUserId(UserId _userId = userId)
{
    userId = _userId;
    return userId;
}

/// <summary>
/// Runs the Entra ID group user membership synchronization job as a static method.
/// </summary>
/// <param name="_roleId">
/// A user for which to perform synchronization; optional.
/// </param>
/// <param name="_userId">
/// A user for which to perform the assignments; optional.
/// </param>
public server static void synchronize(UserId _userId = '')
{
    ADMEntraIdGroupUserSynchronization entraIdGroupSync = new ADMEntraIdGroupUserSynchronization();
    entraIdGroupSync.parmUserId(_userId);
    entraIdGroupSync.runOperation();
}

/// <summary>
/// Subscribes to the first time initialization of an user session
/// to synchronize the Entra ID groups for the current user.
/// </summary>
[SubscribesTo(classStr(ApplicationStartupEventManager), staticDelegateStr(ApplicationStartupEventManager, onInteractiveSessionCreated))]
public static void onInteractiveSessionCreated()
{
    if (ADMEntraIdGroupUserLastSync::syncRequired())
    {
        unchecked(Uncheck::TableSecurityPermission)
        {
            ADMEntraIdGroupUserSynchronization::synchronize(curUserId());
        }
    }
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Reads the optional User ID entered in the dialog.
/// </summary>
public boolean getFromDialog()
{
    boolean ret = super();

    if (dialogUserId)
    {
        userId = dialogUserId.value();
    }

    return ret;
}

public boolean unpack(container _packedClass)
{
    Version version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            return true;
        default:
            return false;
    }
}

/// <summary>
/// Runs the operation. For every enabled ClaimsUser, refreshes the Entra ID group
/// membership snapshot and tracks which groups actually changed. At the end of the
/// run, calls the dynamic role assignment framework once per distinct security role
/// attached to a successfully-refreshed, changed group, then invokes the repair /
/// backfill pass.
/// </summary>
[Microsoft.Dynamics.BusinessPlatform.SharedTypes.InternalUseOnlyAttribute]
public void run()
{
    UserInfo        userInfo;
    Set             dirtyGroups = new Set(Types::String);
    Set             failedUsers = new Set(Types::String);
    container       changeResult;
    container       packedChangedForUser;
    Set             changedForUser;
    boolean         success;
    SetEnumerator   groupEnum;
    int             usersProcessed;
    int             usersSucceeded;
    int             usersWithChanges;

    while select userInfo
        where userInfo.accountType == UserAccountType::ClaimsUser
           && userInfo.isMicrosoftAccount == false
           && userInfo.Enable == NoYes::Yes
           && (!userId || userInfo.id == userId)
    {
        usersProcessed++;

        changeResult = ADMEntraIdGroupHelper::syncEntraIdGroupsforUserWithChangeTracking(userInfo.id);

        [success, packedChangedForUser] = changeResult;

        if (success)
        {
            usersSucceeded++;
            changedForUser = Set::create(packedChangedForUser);

            if (changedForUser && changedForUser.elements() > 0)
            {
                usersWithChanges++;
                groupEnum = changedForUser.getEnumerator();
                while (groupEnum.moveNext())
                {
                    dirtyGroups.add(groupEnum.current());
                }
            }
        }
        else
        {
            failedUsers.add(userInfo.id);
        }
    }

    if (failedUsers.elements() > 0)
    {
        warning(strFmt("@D365FOAdminToolkit:EntraIdGroupSyncFailedUsers", failedUsers.elements()));
    }

    this.synchronizeRolesForDirtyGroups(dirtyGroups);

    ADMEntraIdGroupHelper::ensureDynamicRoleAssignmentRulesForOptedInGroups();

    info(strFmt("@D365FOAdminToolkit:EntraIdSyncRunSummary",
        usersProcessed,
        usersSucceeded,
        failedUsers.elements(),
        usersWithChanges,
        dirtyGroups.elements()));
}

/// <summary>
/// Builds the RunBase dialog with an optional User ID field so an administrator can
/// run the sync for a single user (useful for diagnostics). Leaving the field blank
/// processes all enabled ClaimsUsers as before.
/// </summary>
public Object dialog()
{
    DialogRunbase dialog = super();

    dialogUserId = dialog.addField(extendedTypeStr(UserId),
        "@D365FOAdminToolkit:EntraIdSyncUserIdCaption",
        "@D365FOAdminToolkit:EntraIdSyncUserIdHelp");

    return dialog;
}
